package com.order.order_service.repository; import com.order.order_service.entity.OrderItem; import java.util.List; import org.springframework.data.jpa.repository.JpaRepository; import org.springframework.data.jpa.repository.Query;import org.springframework.data.repository.query.Param; public interface OrderItemRepository extends JpaRepository<OrderItem,Long>{List<OrderItem> findByOrderIdOrderById(Long orderId);@Query("select count(i) from OrderItem i, Order o where i.orderId=o.id and i.restaurantId=:restaurantId and o.userId=:userId and o.status=com.order.order_service.entity.OrderStatus.DELIVERED") long countDeliveredOrders(@Param("userId")Long userId,@Param("restaurantId")Long restaurantId);default boolean hasDeliveredOrder(Long userId,Long restaurantId){return countDeliveredOrders(userId,restaurantId)>0;}@Query("select i.itemName,sum(i.quantity),sum(i.unitPrice*i.quantity) from OrderItem i, Order o where i.orderId=o.id and o.createdAt>=:from and o.createdAt<:to and o.status<>com.order.order_service.entity.OrderStatus.CANCELLED group by i.itemName order by sum(i.quantity) desc")List<Object[]> topItems(@Param("from")java.time.LocalDateTime from,@Param("to")java.time.LocalDateTime to,org.springframework.data.domain.Pageable pageable);}
